@media [not] media-type and  (media-feature: value)
  and  (media-feature: value) {  /* CSS rules to apply
  */}

@media screen and (min-width: 480px) {
  body {

    background-color: lightgreen;
  }
}

@media screen and (min-width: 480px) and (max-width: 768px) {
  body {

    background-color: lightgreen;
  }
}
